head.script:
// https://inswave01.atlassian.net/browse/WAEA-566



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > confirmMessage]<br/>useConfirmMessage=true 일때 중복 Tab 페이지 추가 시 표시되는 Confirm 창에 출력할 텍스트를 설정합니다.",
    "validation" : [
        "addTab() 메소드로 Tab 페이지를 추가할때 동일 ID 의 Tab 페이지가 있는 경우 Confirm 창이 표시됩니다.",
        "Confirm 창에 출력할 텍스트를 설정합니다.",
        "값을 설정하지 않으면 '[{tabOptions.label 파라미터값}]탭이 존재합니다. 기존의 탭을 사용하시려면 '확인'을 새로운 탭을 생성하시려면 '취소'를 선택하세요.' 이 설정됩니다.",
        "Tabs 의 ID 를 기준으로 Tab 페이지의 중복 여부를 판단합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        tabScroll : true,
        useConfirmMessage : true,
        confirmMessage : con_confirmMessage.getText(),
    };

    let cList = $c.gcm.createCList(properties);      

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs4" label="Tabs4"></w2:tabs>';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs5" label="Tabs5"></w2:tabs>';
    strTarget += '<w2:content style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';    
    strTarget += '<w2:textbox id="content3_child" label="content3_child" style="width:200px; height:50px; background-color:var(--ws-gray-300);"></w2:textbox>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content4">';        
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content5">';        
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.getTabCount = function () {
    let rtn = target1.getTabCount();

    wf_body_bottom.getObj("scwin").setReturnValue("getTabCount : " + rtn);
}



scwin.btn_addTab_onclick = async function (e) {
    let id = "tabs1";

    let rowJSON = {};  

    await target1.addTab(id,  
        {   
            "label": "newTabs", 
            "title": "dataObject",            
            "closable": "true"
        }, 
        {   
            "src": "",
            "frameMode" : "wframePreload",
            "scope" : true, 
            "alwaysDraw": true,
            "dataObject":{
                "type" : "json",
                "name" : "tabParam",
                "data" : rowJSON
            }
        }
    );

    scwin.getTabCount();
};
